//
// The C++ side of the key-chain oracle (tests/oracles/keychain.py). Reads one
// synthetic subscriber per line on stdin:
//
//   K OPc RAND SQN AMF MCC MNC SUPI ABBA UL_NAS_COUNT PCI ARFCN
//
// and prints, space-separated in hex, every value of the 5G AKA key chain the
// oracle recomputes from the specification text. The inputs are random test
// data generated by the oracle, never a real subscriber's.

#include <cstdint>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

#include "crypto/keys5g.hpp"
#include "crypto/milenage.hpp"
#include "platform/buf.hpp"
#include "platform/secret.hpp"

using namespace ksim;
using namespace ksim::crypto;

namespace {

std::string h(const SecretBytes& s) {
    return to_hex(s.expose());
}

SecretBytes sec(const std::string& hex) {
    auto r = SecretBytes::from_hex(hex);
    return r ? std::move(*r) : SecretBytes{};
}

} // namespace

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::istringstream in(line);
        std::string k, opc, rand_h, sqn_h, amf_h, mcc, mnc, supi, abba_h;
        std::uint32_t count = 0;
        unsigned pci = 0;
        std::uint32_t arfcn = 0;
        in >> k >> opc >> rand_h >> sqn_h >> amf_h >> mcc >> mnc >> supi >> abba_h >> count >> pci >> arfcn;
        const Bytes rand = *from_hex(rand_h);
        const Bytes sqn = *from_hex(sqn_h);
        const Bytes amf = *from_hex(amf_h);
        const Bytes abba = *from_hex(abba_h);
        const SecretBytes kk = sec(k);
        auto o = milenage::compute(kk, sec(opc), rand, sqn, amf);
        auto snn = keys5g::serving_network_name(mcc, mnc);
        if (!o || !snn) {
            std::cout << "ERROR\n";
            continue;
        }
        Bytes sqn_xor_ak(6);
        for (std::size_t i = 0; i < 6; ++i) {
            sqn_xor_ak[i] = static_cast<std::uint8_t>(sqn[i] ^ o->ak.expose()[i]);
        }
        const SecretBytes kausf = keys5g::kausf(o->ck, o->ik, *snn, sqn_xor_ak);
        const SecretBytes res_star = keys5g::res_star(o->ck, o->ik, *snn, rand, o->res);
        const SecretBytes kseaf = keys5g::kseaf(kausf, *snn);
        auto kamf = keys5g::kamf(kseaf, supi, abba);
        if (!kamf) {
            std::cout << "ERROR\n";
            continue;
        }
        using keys5g::AlgType;
        const SecretBytes kgnb = keys5g::kgnb(*kamf, count);
        const auto ckik = keys5g::ck_ik_prime(o->ck, o->ik, *snn, sqn_xor_ak);
        std::cout << to_hex(o->mac_a) << ' ' << h(o->res) << ' ' << h(o->ck) << ' ' << h(o->ik) << ' ' << h(o->ak)
                  << ' ' << h(o->ak_star) << ' ' << to_hex(o->mac_s) << ' ' << *snn << ' ' << to_hex(sqn_xor_ak)
                  << ' ' << h(kausf) << ' ' << h(res_star) << ' ' << to_hex(keys5g::hres_star(rand, res_star)) << ' '
                  << h(kseaf) << ' ' << h(*kamf) << ' ' << h(*keys5g::algorithm_key(*kamf, AlgType::nas_enc, 2))
                  << ' ' << h(*keys5g::algorithm_key(*kamf, AlgType::nas_int, 2)) << ' ' << h(kgnb) << ' '
                  << h(*keys5g::algorithm_key(kgnb, AlgType::rrc_enc, 2)) << ' '
                  << h(*keys5g::algorithm_key(kgnb, AlgType::rrc_int, 2)) << ' '
                  << h(*keys5g::algorithm_key(kgnb, AlgType::up_enc, 1)) << ' '
                  << h(*keys5g::algorithm_key(kgnb, AlgType::up_int, 1)) << ' ' << h(keys5g::nh(*kamf, kgnb)) << ' '
                  << h(keys5g::kng_ran_star(kgnb, static_cast<std::uint16_t>(pci), arfcn)) << ' '
                  << h(ckik.ck_prime) << ' ' << h(ckik.ik_prime) << '\n';
    }
    return 0;
}
